# -*- coding: utf-8 -*-
"""
推送小红书热点选题报告到微信
支持图片查看 + 表格内容
"""
import requests
import argparse
import os
import sys
import json
from datetime import datetime


def load_config():
    """加载配置文件"""
    config_path = os.path.join(os.path.dirname(os.path.dirname(os.path.abspath(__file__))), 'config.json')
    if os.path.exists(config_path):
        try:
            with open(config_path, 'r', encoding='utf-8') as f:
                return json.load(f)
        except Exception as e:
            print(f"[Warning] Config load failed: {e}")
    return {}


def load_fans_data():
    """
    加载粉丝数据（仅作为备用，优先使用 data.json 自带的粉丝数）

    注意：小红书搜索 API 返回的数据已包含 fans 字段，
    fans.json 仅在需要补充或覆盖时使用
    """
    base_dir = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
    fans_path = os.path.join(base_dir, 'fans.json')
    if os.path.exists(fans_path):
        try:
            with open(fans_path, 'r', encoding='utf-8') as f:
                data = json.load(f)
                # fans.json 格式是 {userId: fans} 或 {"users": {userId: {fans: xxx}}}
                if isinstance(data, dict):
                    # 检查是否是 {"users": {...}} 格式
                    if 'users' in data:
                        users = data['users']
                        result = {uid: info.get('fans', 0) for uid, info in users.items()}
                        print(f"[Info] fans.json (users格式) 加载了 {len(result)} 条记录")
                        return result
                    # 否则是 {userId: fans} 格式
                    print(f"[Info] fans.json (简单格式) 加载了 {len(data)} 条记录")
                    return data
        except Exception as e:
            print(f"[Warning] fans.json 读取失败: {e}")
    else:
        print(f"[Info] fans.json 不存在，将使用 data.json 自带的粉丝数据")
    return {}


def format_number(num):
    """格式化数字"""
    try:
        num = int(num)
    except (ValueError, TypeError):
        num = 0
    if num >= 10000:
        return f"{num/10000:.1f}万"
    return str(num)


def load_data(data_file):
    """加载数据"""
    with open(data_file, 'r', encoding='utf-8') as f:
        raw_data = json.load(f)

    if isinstance(raw_data, dict) and "feeds" in raw_data:
        raw_data = raw_data["feeds"]

    flat_data = []
    for item in raw_data:
        if "noteCard" in item:
            card = item["noteCard"]
            flat_item = {
                "id": item.get('id', ''),
                "title": card.get("displayTitle", "") or "无标题",
                "author": card.get("user", {}).get("nickname", ""),
                "author_id": card.get("user", {}).get("userId", ""),
                "fans": card.get("user", {}).get("fans", 0),
                "likes": card.get("interactInfo", {}).get("likedCount", 0),
                "url": f"https://www.xiaohongshu.com/explore/{item.get('id', '')}"
            }
            flat_data.append(flat_item)
        else:
            # 支持新格式（nickname）和旧格式（author）
            flat_item = {
                "id": item.get('id', ''),
                "title": item.get('title', '无标题'),
                "author": item.get('nickname') or item.get('author', ''),
                "author_id": item.get('userId', ''),
                "fans": item.get('fans', 0),
                "likes": item.get('likedCount', 0) or item.get('likes', 0),
                "url": f"https://www.xiaohongshu.com/explore/{item.get('id', '')}"
            }

# -*- coding: utf-8 -*-
"""
生成图片格式的热点选题报告
微信推送专用 - 图片形式呈现表格
"""
import os
import json
from PIL import Image, ImageDraw, ImageFont
from datetime import datetime


def load_config():
    """加载配置文件"""
    config_path = os.path.join(os.path.dirname(os.path.dirname(os.path.abspath(__file__))), 'config.json')
    if os.path.exists(config_path):
        try:
            with open(config_path, 'r', encoding='utf-8') as f:
                return json.load(f)
        except:
            pass
    return {}


def get_mode_config(mode):
    """获取模式配置"""
    config = load_config()
    if mode == 'lite':
        cfg = config.get('lite_mode', {})
        return {
            'min_likes': cfg.get('min_likes', 500),
            'max_fans': None,
            'time_range': cfg.get('time_range', '2d'),
            'keywords': cfg.get('keywords', [])
        }
    else:
        cfg = config.get('finance_pro_mode', {})
        return {
            'min_likes': cfg.get('min_likes', 1000),
            'max_fans': cfg.get('max_fans', 20000),
            'time_range': cfg.get('time_range', '7d'),
            'keywords': cfg.get('keywords', [])
        }


def format_number(num):
    """格式化数字"""
    if num >= 10000:
        return f"{num/10000:.1f}万"
    return str(num)


def load_data(data_file):
    """加载数据"""
    with open(data_file, 'r', encoding='utf-8') as f:
        raw_data = json.load(f)

    if isinstance(raw_data, dict) and "feeds" in raw_data:
        raw_data = raw_data["feeds"]

    flat_data = []
    for item in raw_data:
        if "noteCard" in item:
            card = item["noteCard"]
            flat_item = {
                "title": card.get("displayTitle", "") or "无标题",
                "author": card.get("user", {}).get("nickname", ""),
                "fans": card.get("user", {}).get("fans", 0),
                "likes": card.get("interactInfo", {}).get("likedCount", 0),
                "url": f"https://www.xiaohongshu.com/explore/{item.get('id', '')}"
            }
            flat_data.append(flat_item)
        else:
            flat_data.append(item)

    return flat_data


def wrap_text(draw, text, font, max_width):
    """文字换行处理"""
    if not text:
        return []
    words = text
    lines = []
    current_line = ""

    for char in words:
        test_line = current_line + char
        bbox = draw.textbbox((0, 0), test_line, font=font)
        width = bbox[2] - bbox[0]
        if width <= max_width:
            current_line = test_line
        else:
            if current_line:
                lines.append(current_line)
            current_line = char

    if current_line:
        lines.append(current_line)

    return lines if lines else [text]

