() => {
  const notes = [];

  // 查找所有笔记卡片
  const noteCards = document.querySelectorAll('section a[href*="/search_result/"]');

  noteCards.forEach(card => {
    try {
      // 提取笔记 ID
      const href = card.getAttribute('href');
      const idMatch = href.match(/\/search_result\/([a-z0-9]+)/);
      const id = idMatch ? idMatch[1] : '';

      // 提取标题
      const titleElement = card.querySelector('.title, [class*="title"]');
      const title = titleElement ? titleElement.textContent.trim() : '';

      // 提取作者名称
      const authorElement = card.querySelector('.author-name, [class*="author"], [class*="name"]');
      const nickname = authorElement ? authorElement.textContent.trim().split(/\s+/)[0] : '';

      // 提取点赞数
      const likeElement = card.querySelector('[class*="like"], [class*="count"]');
      let likedCount = 0;
      if (likeElement) {
        const likeText = likeElement.textContent.trim();
        const likeMatch = likeText.match(/(\d+)/);
        likedCount = likeMatch ? parseInt(likeMatch[1]) : 0;
        // 处理 "1.2万" 格式
        if (likeText.includes('万')) {
          const num = parseFloat(likeText.replace('万', ''));
          likedCount = Math.floor(num * 10000);
        }
      }

      // 提取收藏数（如果有的话）
      const collectElement = card.querySelector('[class*="collect"]');
      let collectedCount = 0;
      if (collectElement) {
        const collectText = collectElement.textContent.trim();
        const collectMatch = collectText.match(/(\d+)/);
        collectedCount = collectMatch ? parseInt(collectMatch[1]) : 0;
      }

      // 提取评论数（如果有的话）
      const commentElement = card.querySelector('[class*="comment"]');
      let commentCount = 0;
      if (commentElement) {
        const commentText = commentElement.textContent.trim();
        const commentMatch = commentText.match(/(\d+)/);
        commentCount = commentMatch ? parseInt(commentMatch[1]) : 0;
      }

      if (id && title) {
        notes.push({
          id,
          title,
          nickname,
          likedCount,
          collectedCount,
          commentCount
        });
      }
    } catch (error) {
      console.error('Error parsing note card:', error);
    }
  });

  return notes;
}

