() => {
  const notes = [];

  // 查找所有笔记链接
  const noteLinks = document.querySelectorAll('a[href*="/search_result/"]');

  noteLinks.forEach(link => {
    try {
      const href = link.getAttribute('href');
      const idMatch = href.match(/\/search_result\/([a-z0-9]+)/);
      const id = idMatch ? idMatch[1] : '';

      if (!id) return;

      // 获取包含这个链接的容器
      let container = link.closest('div');
      if (!container) return;

      // 在同一个父容器中查找标题、作者等信息
      const parent = container.parentElement;
      if (!parent) return;

      // 遍历所有子元素查找标题和作者
      let title = '';
      let nickname = '';
      let likedCount = 0;

      const children = Array.from(parent.children);

      children.forEach(child => {
        const text = child.textContent ? child.textContent.trim() : '';

        // 查找标题（较长的文本，不包含日期）
        if (text.length > 15 && text.length < 100 && 
            !text.includes('昨天') && !text.includes('前') && 
            !text.includes('天前') && !text.includes('-') &&
            !text.includes('小时') && !text.includes('分钟') &&
            !title) {
          title = text;
        }

        // 查找作者名（通常在链接中）
        const authorLink = child.querySelector('a[href*="/user/profile/"]');
        if (authorLink && !nickname) {
          const authorText = authorLink.textContent.trim();
          // 提取第一个词作为作者名
          const parts = authorText.split(/\s+/);
          nickname = parts[0] || '';
        }

        // 查找点赞数（纯数字或带"万"的数字）
        if (!text.includes(id) && text.match(/^\d+(\.\d+)?(万)?$/) && !text.includes('天')) {
          const numMatch = text.match(/(\d+\.?\d*)(万)?/);
          if (numMatch) {
            let num = parseFloat(numMatch[1]);
            if (numMatch[2] === '万') {
              num = num * 10000;
            }
            if (num > likedCount || num < 100000) {
              likedCount = Math.floor(num);
            }
          }
        }
      });

      if (id && title) {
        notes.push({
          id,
          title,
          nickname,
          likedCount,
          collectedCount: 0,
          commentCount: 0
        });
      }
    } catch (error) {
      console.error('Error:', error);
    }
  });

  // 去重（按 ID）
  const seen = new Set();
  return notes.filter(note => {
    if (seen.has(note.id)) return false;
    seen.add(note.id);
    return true;
  });
}

