() => {
  // 查找所有搜索结果链接
  const noteLinks = document.querySelectorAll('a[href*="/search_result/"]');

  // 获取前3个链接的详细信息
  const results = [];

  for (let i = 0; i < Math.min(3, noteLinks.length); i++) {
    const link = noteLinks[i];
    const href = link.getAttribute('href');

    // 向上遍历父元素
    let parent = link.parentElement;
    let level = 0;
    const structure = [];

    while (parent && level < 5) {
      structure.push({
        level,
        tagName: parent.tagName,
        className: parent.className,
        childCount: parent.children.length,
        textPreview: parent.textContent ? parent.textContent.substring(0, 100) : ''
      });

      parent = parent.parentElement;
      level++;
    }

    results.push({
      index: i,
      href,
      structure
    });
  }

  return {
    totalLinks: noteLinks.length,
    samples: results
  };
}

