() => {
  const notes = [];
  const noteLinks = document.querySelectorAll('a[href*="/search_result/"]');

  noteLinks.forEach(link => {
    try {
      // 提取笔记 ID
      const href = link.getAttribute('href');
      const idMatch = href.match(/\/search_result\/([a-z0-9]+)/);
      const id = idMatch ? idMatch[1] : '';

      if (!id) return;

      // 获取父级 DIV（包含所有信息）
      const parentDiv = link.parentElement;
      if (!parentDiv || parentDiv.tagName !== 'DIV') return;

      // 获取所有子元素的文本
      const children = Array.from(parentDiv.children);
      const texts = children.map(child => child.textContent ? child.textContent.trim() : '');

      // 分析文本内容
      let title = '';
      let nickname = '';
      let likedCount = 0;

      // 查找作者链接
      const authorLink = parentDiv.querySelector('a[href*="/user/profile/"]');
      if (authorLink) {
        const authorText = authorLink.textContent.trim();
        // 作者名通常是第一个词
        const parts = authorText.split(/\s+/);
        nickname = parts[0] || '';
      }

      // 遍历所有子元素
      children.forEach(child => {
        const text = child.textContent ? child.textContent.trim() : '';

        // 查找标题（不包含作者名，长度适中）
        if (!text.includes(nickname) && 
            text.length > 10 && text.length < 100 &&
            !text.match(/^\d+$/) && 
            !text.includes('万') &&
            !title) {
          // 进一步检查：不应该包含时间关键词
          if (!text.includes('昨天') && !text.includes('前') && 
              !text.includes('天前') && !text.includes('小时') &&
              !text.includes('分钟') && !text.includes('秒')) {
            title = text;
          }
        }

        // 查找点赞数（纯数字或带"万"）
        const numMatch = text.match(/^(\d+\.?\d*)(万)?$/);
        if (numMatch && !text.includes('天')) {
          let num = parseFloat(numMatch[1]);
          if (numMatch[2] === '万') {
            num = num * 10000;
          }
          if (num > 0 && num < 1000000) {
            likedCount = Math.floor(num);
          }
        }
      });

      // 如果没有找到标题，使用第一个较长的文本
      if (!title) {
        for (const text of texts) {
          if (text.length > 15 && text.length < 100 && text !== nickname) {
            title = text;
            break;
          }
        }
      }

      if (id && title) {
        notes.push({
          id,
          title,
          nickname,
          likedCount,
          collectedCount: 0,
          commentCount: 0
        });
      }
    } catch (error) {
      console.error('Error parsing note:', error);
    }
  });

  // 去重（按 ID）
  const seen = new Set();
  const uniqueNotes = notes.filter(note => {
    if (seen.has(note.id)) return false;
    seen.add(note.id);
    return true;
  });

  return uniqueNotes;
}

() => {
  const notes = [];
  const noteLinks = document.querySelectorAll('a[href*="/search_result/"]');

  noteLinks.forEach(link => {
    try {
      const href = link.getAttribute('href');
      const idMatch = href.match(/\/search_result\/([a-z0-9]+)/);
      const id = idMatch ? idMatch[1] : '';

      if (!id) return;

      const parentDiv = link.parentElement;
      if (!parentDiv || parentDiv.tagName !== 'DIV') return;

      // 获取完整文本
      const fullText = parentDiv.textContent.trim();

      // 提取作者名（从作者链接中）
      let nickname = '';
      const authorLink = parentDiv.querySelector('a[href*="/user/profile/"]');
      if (authorLink) {
        // 找到作者链接中的第一个文本节点
        const nameDiv = authorLink.querySelector('div');
        if (nameDiv) {
          const nameParts = nameDiv.childNodes;
          for (let node of nameParts) {
            if (node.nodeType === Node.TEXT_NODE) {
              const text = node.textContent.trim();
              if (text && !text.includes('昨天') && !text.includes('前') && 
                  !text.includes('天前') && !text.includes('-') &&
                  text.length > 0 && text.length < 20) {
                nickname = text;
                break;
              }
            }
          }
        }
      }

      // 查找所有数字（可能是点赞数）
      const numbers = [];
      fullText.match(/\d+(\.\d+)?(万)?/g)?.forEach(match => {
        let num = parseFloat(match.replace('万', ''));
        if (match.includes('万')) {
          num = num * 10000;
        }
        numbers.push(Math.floor(num));
      });

      // 点赞数通常是中间大小的数字（排除日期）
      let likedCount = 0;
      numbers.sort((a, b) => b - a);
      for (let num of numbers) {
        if (num > 50 && num < 100000 && num !== 2025 && num !== 2026) {
          likedCount = num;
          break;
        }
      }

      // 提取标题 - 在作者名之前，不含数字和时间关键词
      let title = fullText;

      // 移除作者名
      if (nickname) {
        title = title.replace(nickname, '');
      }

      // 移除时间相关内容
      title = title.replace(/昨天\s*\d{1,2}:\d{2}/g, '');
      title = title.replace(/昨天/g, '');
      title = title.replace(/\d+天前/g, '');
      title = title.replace(/\d+小时前/g, '');
      title = title.replace(/\d+分钟前/g, '');
      title = title.replace(/2025-\d{1,2}-\d{1,2}/g, '');
      title = title.replace(/4天前/g, '');
      title = title.replace(/今天/g, '');

      // 移除所有独立的数字
      title = title.replace(/\s+\d+(\.\d+)?(万)?\s*/g, ' ');
      title = title.replace(/\d+(\.\d+)?(万)?/g, '');

      // 清理多余空格
      title = title.trim().replace(/\s+/g, '');

      // 移除末尾的标点符号
      title = title.replace(/[：:,，。！!?]+$/, '');

      if (id && title && title.length > 5) {
        notes.push({
          id,
          title,
          nickname,
          likedCount,
          collectedCount: 0,
          commentCount: 0
        });
      }
    } catch (error) {
      console.error('Error:', error);
    }
  });

  const seen = new Set();
  return notes.filter(note => {
    if (seen.has(note.id)) return false;
    seen.add(note.id);
    return true;
  });
}

